using System.Globalization;
using System.Security.Cryptography;
using System.Text.Json;
using System.Text.Json.Nodes;
using Cortex.Video.Composition;
namespace Cortex.Video;
/// <summary>Schedules selected source spans and embedded sound in Helengine; FFmpeg only encodes the resulting streams.</summary>
public sealed class HelengineCutRenderer(IHelengineCompositionClient client,string ffprobeExecutable="ffprobe",Action<string>? diagnostic=null):IVideoCutRenderer {
    public async Task<RenderedVideo> RenderAsync(string videoPath,TakeEditPlan plan,string outputDirectory,CancellationToken token) {
        string source=Path.GetFullPath(videoPath);if(!File.Exists(source))throw new FileNotFoundException("Selected source is unavailable.",source);var info=await HelengineMediaProbe.ReadAsync(source,ffprobeExecutable,token);if(info.Width<1 || info.Height<1)throw new InvalidDataException("Cuts require a real video stream.");var timeline=CutTimeline.Build(plan,info.Duration);string[] rate=info.Fps.Split('/');long numerator=long.Parse(rate[0],CultureInfo.InvariantCulture),denominator=rate.Length==2?long.Parse(rate[1],CultureInfo.InvariantCulture):1;if(numerator<=0 || denominator<=0)throw new InvalidDataException("Invalid source frame rate.");string sha;await using(var file=File.OpenRead(source))sha=Convert.ToHexStringLower(await SHA256.HashDataAsync(file,token));var layers=new JsonArray();var audio=new JsonArray();
        foreach(var clip in timeline) {layers.Add(new JsonObject{["id"]="picture-"+clip.CandidateId,["media_id"]="source",["kind"]="media",["order"]=0,["start"]=HelengineCompositionCompiler.Time(clip.Start),["end"]=HelengineCompositionCompiler.Time(clip.End),["source_in"]=HelengineCompositionCompiler.Time(clip.SourceStart),["source_out"]=HelengineCompositionCompiler.Time(clip.SourceEnd),["effects"]=new JsonArray(),["animations"]=new JsonArray(),["fit"]="contain"});if(info.HasAudio)audio.Add(new JsonObject{["id"]="audio-"+clip.CandidateId,["media_id"]="source",["start"]=HelengineCompositionCompiler.Time(clip.Start),["end"]=HelengineCompositionCompiler.Time(clip.End),["source_in"]=HelengineCompositionCompiler.Time(clip.SourceStart),["source_out"]=HelengineCompositionCompiler.Time(clip.SourceEnd),["gain"]=1,["muted"]=false,["envelopes"]=new JsonArray()});}
        var composition=new JsonObject{["schema"]="helengine.media.composition.v1",["id"]="cuts-"+Guid.NewGuid().ToString("N"),["revision"]=1,["width"]=info.DisplayWidth,["height"]=info.DisplayHeight,["frame_rate"]=new JsonObject{["numerator"]=numerator,["denominator"]=denominator},["duration"]=HelengineCompositionCompiler.Time(timeline[^1].End),["audio"]=new JsonObject{["enabled"]=info.HasAudio,["sample_rate"]=48000,["channels"]=2},["media"]=new JsonArray(new JsonObject{["id"]="source",["kind"]="video",["path"]=Path.GetFileName(source),["sha256"]=sha,["width"]=info.Width,["height"]=info.Height,["duration"]=HelengineCompositionCompiler.Time(info.Duration)}),["layers"]=layers,["audio_clips"]=audio,["transitions"]=new JsonArray(),["background_color"]="#000000FF"};var document=JsonSerializer.SerializeToElement(composition);string directory=Path.Combine(Path.GetFullPath(outputDirectory),"render-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(directory);string output=Path.Combine(directory,"cut.mp4");await File.WriteAllTextAsync(Path.Combine(directory,"composition.json"),document.GetRawText(),token);diagnostic?.Invoke("Rendering selected video and sound intervals through Helengine.");await client.ValidateAsync(document,Path.GetDirectoryName(source)!,token);await client.RenderAsync(document,Path.GetDirectoryName(source)!,output,"mp4-h264-aac.v1",token);var result=new RenderedVideo(output,timeline[^1].End,timeline);await File.WriteAllTextAsync(Path.Combine(directory,"rendered-video.json"),JsonSerializer.Serialize(result,VideoNodes.JsonOptions),token);return result;
    }
}
